{
  "unit_id": "p8",
  "status": "REVIEWED",
  "reason": "Inventory of explicit directives in p8/p9 fragments, retaining parent/neighbor context and unresolved cross-references.",
  "requirements": [
    {
      "local_id": "p8_mobile_data_airplane_mode",
      "action": "guide_user_to_disable_airplane_mode",
      "action_spans": [
        {
          "source_id": "p7",
          "quote": "Refer to the \"Understanding and Troubleshooting Your Phone's Cellular Service\" section for instructions on how to check and turn off Airplane Mode."
        }
      ],
      "scope": "mobile_data_unavailable",
      "source_spans": [
        {
          "source_id": "p7",
          "quote": "Airplane Mode is ON: Disables all wireless connections, including mobile data."
        }
      ],
      "modality": "REQUIRE",
      "condition": {
        "op": "ATOM",
        "label": "airplane_mode_enabled",
        "spans": [
          {
            "source_id": "p7",
            "quote": "Airplane Mode is ON"
          }
        ],
        "children": []
      },
      "guard": null,
      "exceptions": [],
      "open_questions": []
    },
    {
      "local_id": "p8_mobile_data_toggle",
      "action": "guide_user_to_toggle_mobile_data",
      "action_spans": [
        {
          "source_id": "p7",
          "quote": "guide the user to use `toggle_data()` to turn mobile data ON."
        }
      ],
      "scope": "mobile_data_disabled",
      "source_spans": [
        {
          "source_id": "p7",
          "quote": "Mobile Data is Turned OFF: The main switch for mobile data might be disabled in the phone's settings."
        }
      ],
      "modality": "REQUIRE",
      "condition": {
        "op": "ATOM",
        "label": "mobile_data_disabled",
        "spans": [
          {
            "source_id": "p7",
            "quote": "`check_network_status()` shows mobile data is disabled"
          }
        ],
        "children": []
      },
      "guard": null,
      "exceptions": [],
      "open_questions": []
    },
    {
      "local_id": "p8_roaming_enable",
      "action": "guide_user_to_enable_roaming",
      "action_spans": [
        {
          "source_id": "p7",
          "quote": "guide them to use `toggle_roaming()` to ensure Data Roaming is ON."
        }
      ],
      "scope": "data_roaming_disabled_abroad",
      "source_spans": [
        {
          "source_id": "p7",
          "quote": "Data Roaming is turned OFF on the phone."
        }
      ],
      "modality": "REQUIRE",
      "condition": {
        "op": "AND",
        "label": "user_abroad_and_roaming_disabled",
        "spans": [
          {
            "source_id": "p7",
            "quote": "Roaming Issues (When User is Abroad)"
          }
        ],
        "children": [
          {
            "op": "ATOM",
            "label": "user_abroad",
            "spans": [
              {
                "source_id": "p7",
                "quote": "When User is Abroad"
              }
            ],
            "children": []
          },
          {
            "op": "ATOM",
            "label": "roaming_disabled",
            "spans": [
              {
                "source_id": "p7",
                "quote": "Data Roaming is turned OFF on the phone."
              }
            ],
            "children": []
          }
        ]
      },
      "guard": {
        "op": "NOT",
        "label": "line_roaming_enabled",
        "spans": [
          {
            "source_id": "p7",
            "quote": "the line is not roaming enabled"
          }
        ],
        "children": [
          {
            "op": "ATOM",
            "label": "line_roaming_enabled_check",
            "spans": [
              {
                "source_id": "p7",
                "quote": "You should check that the line associated with the phone number the user provided is roaming enabled."
              }
            ],
            "children": []
          }
        ]
      },
      "exceptions": [],
      "open_questions": [
        "How to programmatically verify if the line is roaming-enabled?"
      ]
    },
    {
      "local_id": "p8_data_saver_mode",
      "action": "guide_user_to_disable_data_saver",
      "action_spans": [
        {
          "source_id": "p8",
          "quote": "guide the user to use `toggle_data_saver_mode()` to turn it OFF."
        }
      ],
      "scope": "data_saver_mode_active",
      "source_spans": [
        {
          "source_id": "p8",
          "quote": "Data Saver mode is a feature that restricts background data usage and can affect data speeds."
        }
      ],
      "modality": "REQUIRE",
      "condition": {
        "op": "ATOM",
        "label": "data_saver_mode_on",
        "spans": [
          {
            "source_id": "p8",
            "quote": "`check_data_restriction_status()` shows \"Data Saver mode is ON\""
          }
        ],
        "children": []
      },
      "guard": null,
      "exceptions": [],
      "open_questions": []
    },
    {
      "local_id": "p8_vpn_disconnect",
      "action": "guide_user_to_disconnect_vpn",
      "action_spans": [
        {
          "source_id": "p8",
          "quote": "guide the user to use `disconnect_vpn()` to disconnect the VPN."
        }
      ],
      "scope": "vpn_connected_and_performance_poor",
      "source_spans": [
        {
          "source_id": "p8",
          "quote": "VPN (Virtual Private Network) is a feature that encrypts internet traffic and can help improve data speeds and security."
        }
      ],
      "modality": "REQUIRE",
      "condition": {
        "op": "AND",
        "label": "vpn_connected_and_performance_poor",
        "spans": [
          {
            "source_id": "p8",
            "quote": "VPN Connection Issues"
          }
        ],
        "children": [
          {
            "op": "ATOM",
            "label": "vpn_connected",
            "spans": [
              {
                "source_id": "p8",
                "quote": "`check_vpn_status()` shows \"VPN is ON and connected\""
              }
            ],
            "children": []
          },
          {
            "op": "ATOM",
            "label": "performance_poor",
            "spans": [
              {
                "source_id": "p8",
                "quote": "performance level is \"Poor\""
              }
            ],
            "children": []
          }
        ]
      },
      "guard": null,
      "exceptions": [],
      "open_questions": []
    },
    {
      "local_id": "p8_data_plan_upgrade",
      "action": "guide_user_to_upgrade_data_plan",
      "action_spans": [
        {
          "source_id": "p8",
          "quote": "Change to a plan with more data."
        },
        {
          "source_id": "p8",
          "quote": "Add more data to the line by \"refueling\" data at a price per GB specified by the plan."
        }
      ],
      "scope": "data_plan_limit_reached",
      "source_spans": [
        {
          "source_id": "p8",
          "quote": "Data Plan Limits Reached: The user may have used up their monthly data allowance, and the carrier has slowed down or cut off data."
        }
      ],
      "modality": "REQUIRE",
      "condition": {
        "op": "ATOM",
        "label": "data_usage_exceeds_limit",
        "spans": [
          {
            "source_id": "p8",
            "quote": "the user's data usage for a line associated with the phone number the user provided exceeds the plan's data limit"
          }
        ],
        "children": []
      },
      "guard": null,
      "exceptions": [],
      "open_questions": [
        "How to programmatically verify the user's current data usage?"
      ]
    },
    {
      "local_id": "p8_network_mode_upgrade",
      "action": "guide_user_to_upgrade_network_mode",
      "action_spans": [
        {
          "source_id": "p8",
          "quote": "guide the user to use `set_network_mode_preference(mode: str)` with the mode `\"4g_5g_preferred\"`"
        }
      ],
      "scope": "network_mode_2g_or_3g",
      "source_spans": [
        {
          "source_id": "p8",
          "quote": "Using older modes like 2G/3G can significantly limit speed."
        }
      ],
      "modality": "REQUIRE",
      "condition": {
        "op": "OR",
        "label": "network_mode_2g_or_3g",
        "spans": [
          {
            "source_id": "p8",
            "quote": "Optimizing Network Mode Preferences"
          }
        ],
        "children": [
          {
            "op": "ATOM",
            "label": "network_mode_2g",
            "spans": [
              {
                "source_id": "p8",
                "quote": "`check_network_mode_preference()` shows \"2G\""
              }
            ],
            "children": []
          },
          {
            "op": "ATOM",
            "label": "network_mode_3g",
            "spans": [
              {
                "source_id": "p8",
                "quote": "`check_network_mode_preference()` shows \"3G\""
              }
            ],
            "children": []
          }
        ]
      },
      "guard": null,
      "exceptions": [],
      "open_questions": []
    },
    {
      "local_id": "p8_mms_network_mode_upgrade",
      "action": "guide_user_to_upgrade_network_mode_for_mms",
      "action_spans": [
        {
          "source_id": "p9",
          "quote": "guide the user to use `set_network_mode_preference(mode: str)` to switch to a network mode that includes 3G, 4G, or 5G (e.g., `\"4g_5g_preferred\"` or `\"4g_only\"`)."
        }
      ],
      "scope": "mms_network_2g",
      "source_spans": [
        {
          "source_id": "p9",
          "quote": "MMS requires at least a 3G network connection; 2G networks are generally not suitable."
        }
      ],
      "modality": "REQUIRE",
      "condition": {
        "op": "ATOM",
        "label": "network_mode_2g_for_mms",
        "spans": [
          {
            "source_id": "p9",
            "quote": "`check_network_status()` shows \"2G\""
          }
        ],
        "children": []
      },
      "guard": null,
      "exceptions": [],
      "open_questions": []
    },
    {
      "local_id": "p8_mms_apn_reset",
      "action": "guide_user_to_reset_apn_settings",
      "action_spans": [
        {
          "source_id": "p9",
          "quote": "guide the user to use `reset_apn_settings()` to reset the APN settings."
        },
        {
          "source_id": "p9",
          "quote": "instructed to use `reboot_device()` for the changes to apply."
        }
      ],
      "scope": "mms_apn_missing_or_incorrect",
      "source_spans": [
        {
          "source_id": "p9",
          "quote": "Incorrect APN Settings: Specifically, a missing or incorrect MMSC URL."
        }
      ],
      "modality": "REQUIRE",
      "condition": {
        "op": "ATOM",
        "label": "mmsc_url_not_set",
        "spans": [
          {
            "source_id": "p9",
            "quote": "`check_apn_settings()` shows MMSC URL is not set"
          }
        ],
        "children": []
      },
      "guard": null,
      "exceptions": [],
      "open_questions": []
    },
    {
      "local_id": "p8_mms_wifi_calling_disable",
      "action": "guide_user_to_disable_wifi_calling",
      "action_spans": [
        {
          "source_id": "p9",
          "quote": "guide the user to use `toggle_wifi_calling()` to turn it OFF."
        }
      ],
      "scope": "wifi_calling_interfering_with_mms",
      "source_spans": [
        {
          "source_id": "p9",
          "quote": "Wi-Fi Calling settings can sometimes conflict with MMS functionality."
        }
      ],
      "modality": "REQUIRE",
      "condition": {
        "op": "ATOM",
        "label": "wifi_calling_on",
        "spans": [
          {
            "source_id": "p9",
            "quote": "`check_wifi_calling_status()` shows \"Wi-Fi Calling is ON\""
          }
        ],
        "children": []
      },
      "guard": null,
      "exceptions": [],
      "open_questions": []
    },
    {
      "local_id": "p8_mms_basic_connectivity_check",
      "action": "verify_basic_connectivity_for_mms",
      "action_spans": [
        {
          "source_id": "p9",
          "quote": "ensure the user can make calls and that their mobile data is working for other apps (e.g., browsing the web)."
        }
      ],
      "scope": "mms_connectivity_issues",
      "source_spans": [
        {
          "source_id": "p9",
          "quote": "No Cellular Service or Mobile Data Off/Not Working: The most common reasons. MMS relies on these."
        }
      ],
      "modality": "REQUIRE",
      "condition": {
        "op": "OR",
        "label": "no_cellular_service_or_mobile_data_off",
        "spans": [
          {
            "source_id": "p9",
            "quote": "No Cellular Service or Mobile Data Off/Not Working"
          }
        ],
        "children": [
          {
            "op": "ATOM",
            "label": "no_cellular_service",
            "spans": [
              {
                "source_id": "p9",
                "quote": "No Cellular Service"
              }
            ],
            "children": []
          },
          {
            "op": "ATOM",
            "label": "mobile_data_off",
            "spans": [
              {
                "source_id": "p9",
                "quote": "Mobile Data Off/Not Working"
              }
            ],
            "children": []
          }
        ]
      },
      "guard": null,
      "exceptions": [],
      "open_questions": [
        "How to programmatically verify if the user can make calls?"
      ]
    }
  ]
}
